const colors=[{name:'Milk',ru:'Молочный',hex:'#eee7d8',ink:'#292d2a'},{name:'Denim blue',ru:'Джинсовый синий',hex:'#477a9c',ink:'#f4eddc'},{name:'Sand honey',ru:'Песочно-медовый',hex:'#d8ac66',ink:'#292d2a'},{name:'Ice blue',ru:'Ледяной голубой',hex:'#b9d4e1',ink:'#292d2a'},{name:'Muted wine',ru:'Приглушённый винный',hex:'#753644',ink:'#f5e9d3'},{name:'Graphite',ru:'Графит',hex:'#3d4142',ink:'#f4eddc'}];
const cases=[{name:'Silver aluminum',hex:'#b8bdbb'},{name:'Ivory',hex:'#d9d2bf'},{name:'Deep blue',hex:'#253b53'},{name:'Black',hex:'#252725'}];let selectedCase=0,selectedKey=3;
let legendMode='dual',surface='satin',switchType='linear';
function illustratedBoard(ci,ki,id='kb'){
const c=cases[ci],k=colors[ki];
const grad=(n,st)=>`<linearGradient id="${id+n}" x1="0" y1="0" x2="0.15" y2="1">${st.map(([o,col,op])=>`<stop offset="${o}" stop-color="${col}" stop-opacity="${op??1}"/>`).join('')}</linearGradient>`;
let out=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 378" role="presentation"><defs>${grad('case',[[0,'#fff',.7],[.08,'#fff',.22],[.48,'#fff',.04],[1,'#000',.23]])}${grad('side',[[0,'#000',.1],[1,'#000',.5]])}${grad('cap',[[0,'#fff',.25],[.35,'#fff',.05],[1,'#000',.17]])}${grad('dish',[[0,'#000',.16],[.45,'#000',.02],[1,'#fff',.17]])}${grad('dial',[[0,'#373735'],[.25,'#262725'],[1,'#111310']])}<filter id="${id}shadow" x="-30%" y="-30%" width="160%" height="180%"><feDropShadow dx="0" dy="4" stdDeviation="2" flood-opacity=".65"/></filter><filter id="${id}grain"><feTurbulence type="fractalNoise" baseFrequency=".8" numOctaves="2" seed="4"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope="${surface==='brushed'?.13:.035}"/></feComponentTransfer><feBlend in="SourceGraphic" mode="soft-light"/></filter></defs>
<rect x="5" y="17" width="890" height="352" rx="26" fill="${c.hex}"/><rect x="5" y="17" width="890" height="352" rx="26" fill="url(#${id}side)"/><rect x="5" y="5" width="890" height="347" rx="25" fill="${c.hex}"/><rect x="5" y="5" width="890" height="347" rx="25" fill="url(#${id}case)" stroke="#fff" stroke-opacity=".42" stroke-width="1.5" filter="url(#${id}grain)"/>
<rect x="20" y="20" width="807" height="316" rx="12" fill="#121915" stroke="#000" stroke-opacity=".5" stroke-width="3"/><rect x="22" y="22" width="803" height="311" rx="10" fill="#303932"/>`;
const key=(x,y,w,h,label,col,ink)=>{
let q=`<g filter="url(#${id}shadow)"><rect x="${x}" y="${y+3}" width="${w}" height="${h}" rx="6" fill="${col}"/><rect x="${x}" y="${y+3}" width="${w}" height="${h}" rx="6" fill="#000" opacity=".35"/><rect x="${x}" y="${y}" width="${w}" height="${h-1}" rx="6" fill="${col}"/><rect x="${x}" y="${y}" width="${w}" height="${h-1}" rx="6" fill="url(#${id}cap)"/><rect x="${x+4}" y="${y+2}" width="${w-8}" height="${h-10}" rx="5" fill="${col}"/><rect x="${x+4}" y="${y+2}" width="${w-8}" height="${h-10}" rx="5" fill="url(#${id}dish)" stroke="#fff" stroke-opacity=".17" stroke-width=".6"/></g>`;
let parts=label.split(' '); if(label==='SPACE'&&legendMode!=='blank'){q+=`<path d="M${x+10} ${y+30} C${x+65} ${y+8},${x+105} ${y+43},${x+w-66} ${y+13} C${x+w-11} ${y-2},${x+w+1} ${y+8},${x+w-9} ${y+26} C${x+w-20} ${y+39},${x+90} ${y+33},${x+10} ${y+30}Z" fill="${ink}"/><ellipse cx="${x+w-43}" cy="${y+19}" rx="13" ry="5.5" transform="rotate(-10 ${x+w-43} ${y+19})" fill="${col}"/>`;}else if(legendMode!=='blank'){q+=`<text x="${x+9}" y="${y+16}" font-family="Arial,sans-serif" font-size="${parts[0].length>4?8:10}" font-weight="500" fill="${ink}">${parts[0].replaceAll('&','&amp;')}</text>`;if(parts[1]&&legendMode==='dual')q+=`<text x="${x+w-9}" y="${y+31}" text-anchor="end" font-family="Arial" font-size="9" fill="${ink}" opacity=".65">${parts[1].replaceAll('&','&amp;')}</text>`;}if(legendMode!=='blank'&&['Esc','Tab','Caps','Shift','Backspace','F4','F8','F12','Del','PgUp','PgDn','↑','↓','←','→','Enter'].includes(label)){const large=label==='Enter';q+=`<path d="M${x+(large?w*.48:8)} ${y+h-10} C${x+w*.65} ${y+h-8},${x+w-10} ${y+(large?28:36)},${x+w-8} ${y+(large?7:23)} Q${x+w-2} ${y+h-5} ${x+w*.7} ${y+h-6} Z" fill="${ink}"/>`;}if(label==='F А'||label==='J О')q+=`<rect x="${x+w/2-4}" y="${y+h-12}" width="8" height="1.2" rx=".6" fill="${ink}" opacity=".5"/>`;return q;
};
const rows=[['Esc','F1','F2','F3','F4','F5','F6','F7','F8','F9','F10','F11','F12','Del'],['~ Ё','1 !','2 @','3 #','4 $','5 %','6 ^','7 &','8 *','9 (','0 )','− _','= +','Backspace'],['Tab','Q Й','W Ц','E У','R К','T Е','Y Н','U Г','I Ш','O Щ','P З','[ Х','] Ъ','\\'],['Caps','A Ф','S Ы','D В','F А','G П','H Р','J О','K Л','L Д','; Ж','’ Э','Enter'],['Shift','Z Я','X Ч','C С','V М','B И','N Т','M Ь',', Б','. Ю','/ ?','Shift'],['Ctrl','Win','Alt','SPACE','Alt','Fn','Ctrl']];
rows.forEach((row,r)=>{let x=27;const widths=row.map((v,i)=>r===0?51:r===1?(i===13?100:48):r===2?(i===0?70:i===13?78:48):r===3?(i===0?83:i===12?117:48):r===4?(i===0?107:i===11?90:48):(v==='SPACE'?275:61));row.forEach((v,i)=>{out+=key(x,[28,82,132,182,232,282][r],widths[i],r===0?40:41,v,k.hex,k.ink);x+=widths[i]+5;});});
out+=`<ellipse cx="854" cy="52" rx="29" ry="27" fill="#000" opacity=".45"/><circle cx="854" cy="48" r="25" fill="url(#${id}dial)" stroke="#151b17" stroke-width="2"/>`;
for(let i=0;i<56;i++){const t=i*Math.PI/28;out+=`<path d="M${854+23*Math.cos(t)} ${48+23*Math.sin(t)} L${854+25*Math.cos(t)} ${48+25*Math.sin(t)}" stroke="#e7eee3" stroke-opacity=".09" stroke-width=".7"/>`;}
out+=`<circle cx="854" cy="45" r="20" fill="url(#${id}dial)" stroke="#454642" stroke-opacity=".25"/>`;
['Home','PgUp','PgDn'].forEach((v,i)=>{out+=key(834,88+i*49,42,40,v,k.hex,k.ink);});out+=key(778,235,44,40,'↑',k.hex,k.ink);['←','↓','→'].forEach((v,i)=>{out+=key(726+i*51,284,44,40,v,k.hex,k.ink);});out+=`<circle cx="839" cy="342" r="1.7" fill="#b4d8a0"/><text x="52" y="344" fill="#17251b" fill-opacity=".5" font-family="Arial" font-size="6" letter-spacing="3">F O R M / 0 1</text></svg>`;return out;}
// Clip to the selected source row before fitting it inside the preview.
function board(ci,ki,id='kb'){
 if(legendMode!=='dual')return illustratedBoard(ci,ki,id);
 const photo=new URL('keyboard-palettes.png',document.baseURI).href;
 const offset=ki*256;
 const tint=ci===0?'':`<rect x="168" y="${offset+9}" width="692" height="238" fill="${cases[ci].hex}" mask="url(#${id}frame)" style="mix-blend-mode:multiply" opacity="${ci===1?.65:.92}"/>`;
 const texture=surface==='brushed'?`<rect x="168" y="${offset+9}" width="692" height="238" fill="url(#${id}brushed)" mask="url(#${id}frame)"/>`:'';
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 378" role="presentation"><defs><clipPath id="${id}row"><rect x="130" y="${offset}" width="770" height="256"/></clipPath><mask id="${id}frame" maskUnits="userSpaceOnUse" x="130" y="${offset}" width="770" height="256"><rect x="168" y="${offset+9}" width="692" height="238" rx="20" fill="white"/><rect x="182" y="${offset+18}" width="664" height="207" rx="9" fill="black"/></mask><pattern id="${id}brushed" width="6" height="2" patternUnits="userSpaceOnUse"><path d="M0 .5h6" stroke="#fff" stroke-opacity=".16" stroke-width=".5"/></pattern></defs><svg x="0" y="15" width="900" height="345" viewBox="130 ${offset} 770 256" overflow="hidden"><g clip-path="url(#${id}row)" style="isolation:isolate"><image href="${photo}" width="1024" height="1536"/>${tint}${texture}</g></svg></svg>`;
}
if(document.querySelector('#hero-board'))document.querySelector('#hero-board').innerHTML=board(0,3,'hero');if(document.querySelector('#color-cards'))document.querySelector('#color-cards').innerHTML=[3,4,5].map((i)=>{const c=colors[i];return `<button class="card" data-key="${i}" aria-label="Configure ${c.name} keycaps"><div class="card-top"><span>0${i+1} / ${c.ru.toUpperCase()}</span><span>EN + RU</span></div>${board(0,i,'card'+i)}<div class="card-bottom"><strong>${c.name}</strong><span>↗</span></div></button>`;}).join('');
function render(){document.querySelector('#config-board').innerHTML=board(selectedCase,selectedKey,'config');document.querySelector('#config-board').setAttribute('aria-label',`${cases[selectedCase].name} case with ${colors[selectedKey].name} keycaps, generated concept preview`);document.querySelector('#case-name').textContent=cases[selectedCase].name;document.querySelector('#key-name').textContent=colors[selectedKey].name;document.querySelector('#combo-caption').textContent=`${cases[selectedCase].name.toUpperCase()} / ${colors[selectedKey].name.toUpperCase()}`;for(const [group,items,sel] of [['cases',cases,selectedCase],['keys',colors,selectedKey]])document.querySelector('#'+group).innerHTML=items.map((c,i)=>`<button class="swatch" style="background:${c.hex}" aria-label="${c.name}" title="${c.name}" aria-pressed="${sel===i}" data-group="${group}" data-index="${i}"></button>`).join('');}
document.addEventListener('click',e=>{const sw=e.target.closest('.swatch');if(sw){if(sw.dataset.group==='cases')selectedCase=Number(sw.dataset.index);else selectedKey=Number(sw.dataset.index);render();history.replaceState(null,'',`?case=${selectedCase}&color=${selectedKey}#configure`);document.querySelector('#status').textContent='';}const card=e.target.closest('.card[data-key]');if(card){selectedKey=Number(card.dataset.key);render();document.querySelector('#configure').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
const params=new URLSearchParams(location.search);const savedCase=Number(params.get('case')),savedKey=Number(params.get('color'));if(Number.isInteger(savedCase)&&savedCase>=0&&savedCase<cases.length)selectedCase=params.has('case')?savedCase:0;if(Number.isInteger(savedKey)&&savedKey>=0&&savedKey<colors.length)selectedKey=params.has('color')?savedKey:3;if(document.querySelector('#config-board'))render();
document.querySelector('#save-build')?.addEventListener('click',async()=>{let svg=board(selectedCase,selectedKey,'saved').replace('viewBox="0 0 900 378"','viewBox="0 0 900 510"').replace(/<\/svg>$/,`<text x="28" y="420" font-family="Arial" font-size="25" fill="#252c29">FORM / ${cases[selectedCase].name} + ${colors[selectedKey].name}</text><text x="28" y="451" font-family="Arial" font-size="14" fill="#60685c">English + Russian · Character collection · Illustrated concept</text><text x="28" y="480" font-family="Arial" font-size="12" fill="#60685c">Availability and pricing to be confirmed.</text></svg>`);if(svg.includes('keyboard-palettes.png')){try{const response=await fetch(new URL('keyboard-palettes.png',document.baseURI));if(!response.ok)throw Error('image');const blob=await response.blob();const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});svg=svg.replace(new URL('keyboard-palettes.png',document.baseURI).href,data);}catch{document.querySelector('#status').textContent='Build card could not be downloaded. Save or share your build instead.';return;}}const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download=`form-${cases[selectedCase].name.toLowerCase().replaceAll(' ','-')}-${colors[selectedKey].name.toLowerCase().replaceAll(' ','-')}.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#status').textContent='Your build card has been downloaded.';});

if(document.querySelector('#config-board')){
const baseRender=render;
render=function(){baseRender();const caption=document.querySelector('.art-caption span:last-child');if(caption)caption.textContent=legendMode==='dual'?'PHOTO-STYLE CONCEPT PREVIEW':'ILLUSTRATED LEGEND PREVIEW';if(document.querySelector('#macro-board'))document.querySelector('#macro-board').innerHTML=board(selectedCase,selectedKey,'macro');document.querySelector('#legend-label').textContent={dual:'English + Russian',en:'English',blank:'Blank'}[legendMode];document.querySelector('#legend-mode').value=legendMode;document.querySelector('#surface').value=surface;document.querySelector('#switch-type').value=switchType;};
function state(){return {c:selectedCase,k:selectedKey,l:legendMode,f:surface,s:switchType};}
function apply(b){if(!b||typeof b!=='object')return;for(const [key,max] of [['c',cases.length],['k',colors.length]]){if(!Number.isInteger(b[key])||b[key]<0||b[key]>=max)return;}selectedCase=b.c;selectedKey=b.k;legendMode=['dual','en','blank'].includes(b.l)?b.l:'dual';surface=b.f==='brushed'?'brushed':'satin';switchType=['linear','tactile','clicky'].includes(b.s)?b.s:'linear';render();}
function updateURL(){const u=new URL(location.href);u.searchParams.set('build',JSON.stringify(state()));u.searchParams.delete('case');u.searchParams.delete('color');history.replaceState(null,'',u);}
document.addEventListener('click',e=>{if(e.target.closest('.swatch,.card'))updateURL();});
for(const name of ['legend-mode','surface','switch-type'])document.querySelector('#'+name).addEventListener('change',e=>{if(name==='legend-mode')legendMode=e.target.value;if(name==='surface')surface=e.target.value;if(name==='switch-type')switchType=e.target.value;render();updateURL();});
let builds=[];try{builds=JSON.parse(localStorage.getItem('form-builds')||'[]');if(!Array.isArray(builds))builds=[];}catch{};
function showBuilds(){const el=document.querySelector('#saved-builds');el.replaceChildren();builds.forEach((b,i)=>{const row=document.createElement('div'),btn=document.createElement('button'),del=document.createElement('button');btn.textContent=`${cases[b.c]?.name||'Case'} / ${colors[b.k]?.name||'Color'}`;btn.onclick=()=>{apply(b);updateURL();};del.textContent='×';del.setAttribute('aria-label','Delete saved build '+(i+1));del.onclick=()=>{builds.splice(i,1);persist();showBuilds();};row.append(btn,del);el.append(row);});}
function persist(){try{localStorage.setItem('form-builds',JSON.stringify(builds));return true;}catch{document.querySelector('#status').textContent='Browser storage is unavailable. Use a build link to keep this combination.';return false;}}
document.querySelector('#remember-build').onclick=()=>{builds.unshift(state());builds=builds.slice(0,12);if(persist())document.querySelector('#status').textContent='Saved to this browser.';showBuilds();};
document.querySelector('#share-build').onclick=async()=>{updateURL();try{await navigator.clipboard.writeText(location.href);document.querySelector('#status').textContent='Build link copied.';}catch{document.querySelector('#status').textContent='Copy this build link from your browser’s address bar.';}};
let audio,playing=false;
document.querySelector('#play-sound').onclick=async()=>{if(playing)return;const btn=document.querySelector('#play-sound');try{audio ||= new (window.AudioContext||window.webkitAudioContext)();await audio.resume();playing=true;btn.textContent='Playing…';btn.disabled=true;const v=Number(document.querySelector('#volume').value),type=switchType;for(let i=0;i<13;i++){let t=audio.currentTime+i*.105+Math.sin(i*3)*.015;const duration=type==='linear'?.11:type==='tactile'?.085:.065;let buf=audio.createBuffer(1,audio.sampleRate*duration,audio.sampleRate),d=buf.getChannelData(0);let seed=1234+i*735;for(let j=0;j<d.length;j++){seed=(seed*16807)%2147483647;const n=seed/1073741824-1,sec=j/audio.sampleRate;d[j]=(n*.6+Math.sin(2*Math.PI*(type==='linear'?175:type==='tactile'?310:620)*sec)*.4)*Math.exp(-sec*(type==='linear'?45:70));}let src=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();src.buffer=buf;filter.type='lowpass';filter.frequency.value=type==='linear'?1200:type==='tactile'?2600:6500;gain.gain.value=v*.5;src.connect(filter).connect(gain).connect(audio.destination);src.start(t);if(type==='clicky'){const osc=audio.createOscillator(),g=audio.createGain();osc.frequency.value=3100;g.gain.setValueAtTime(v*.07,t+.018);g.gain.exponentialRampToValueAtTime(.001,t+.035);osc.connect(g).connect(audio.destination);osc.start(t+.018);osc.stop(t+.04);}}setTimeout(()=>{playing=false;btn.disabled=false;btn.textContent='▶ Hear this build';},1700);}catch{playing=false;btn.disabled=false;btn.textContent='▶ Hear this build';document.querySelector('#status').textContent='Audio is unavailable in this browser.';}};
try{const b=new URLSearchParams(location.search).get('build');if(b)apply(JSON.parse(b));}catch{}render();showBuilds();

}
